import networkx as nx

def has_eulerian_path(G, source=None):
    if not isinstance(G, nx.Graph):
        raise ValueError("Input must be a NetworkX graph.")

    # Count the number of vertices with odd degree
    odd_degree_count = sum(1 for v in G.nodes() if G.degree[v] % 2 == 1)

    if odd_degree_count > 2:
        return False  # More than 2 vertices with odd degree means no Eulerian path

    if source is not None:
        if G.degree[source] % 2 == 0:
            return False  # Source must have odd degree to start an Eulerian path
        return odd_degree_count == 1  # Only one odd degree vertex allows Eulerian path starting at source
    else:
        return odd_degree_count in [0, 2]  # No odd degree or exactly two odd degree vertices

