import networkx as nx

def triadic_census_digraph(G, nodelist=None):
    if nodelist is not None:
        G = G.subgraph(nodelist)

    census = {i: 0 for i in range(16)}

    for u in G.nodes():
        for v in G.nodes():
            if u != v:
                for w in G.nodes():
                    if w != u and w != v:
                        triad = (u, v, w)
                        adj = [G.has_edge(u, v), G.has_edge(v, u),
                               G.has_edge(v, w), G.has_edge(w, v),
                               G.has_edge(w, u), G.has_edge(u, w)]
                        code = (
                            adj[0] * 8 + adj[1] * 4 +
                            adj[2] * 2 + adj[3] * 1 +
                            adj[4] * 1 + adj[5] * 1
                        )
                        census[code] += 1

    return census

