import networkx as nx

# Create an ordered directed graph
class OrderedDiGraph(nx.DiGraph):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)

    def edges(self, *args, **kwargs):
        # Return the edges in a consistent order
        return sorted(super().edges(*args, **kwargs), key=lambda x: (self.nodes[x[0]]['order'], self.nodes[x[1]]['order']))

    def add_node(self, node, **attr):
        if 'order' not in attr:
            attr['order'] = len(self.nodes)  # Assign an order based on current node count
        super().add_node(node, **attr)

