import numpy as np

def compute_simrank(G, C=0.8, max_iter=100, tol=1e-6):
    nodes = list(G.nodes())
    n = len(nodes)

    # Initialize the similarity matrix
    S = np.zeros((n, n))

    # Create a mapping from node to index
    node_to_index = {node: i for i, node in enumerate(nodes)}

    # Pre-compute neighbors for each node
    neighbors = {node: set(G.neighbors(node)) for node in nodes}

    for iteration in range(max_iter):
        S_prev = S.copy()

        for i in range(n):
            for j in range(n):
                if i != j:
                    sim = 0.0
                    for neighbor_i in neighbors[nodes[i]]:
                        for neighbor_j in neighbors[nodes[j]]:
                            if neighbor_i in node_to_index and neighbor_j in node_to_index:
                                sim += S_prev[node_to_index[neighbor_i], node_to_index[neighbor_j]]
                    S[i, j] = (C / (len(neighbors[nodes[i]]) * len(neighbors[nodes[j]]))) * sim if len(neighbors[nodes[i]]) > 0 and len(neighbors[nodes[j]]) > 0 else 0

        # Check for convergence
        if np.linalg.norm(S - S_prev) < tol:
            break

    return S

# Example usage
