def random_state_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        # Create an instance of RandomState
        random_state = np.random.RandomState()
        # Pass the random_state to the decorated function
        return func(random_state, *args, **kwargs)
    return wrapper

@random_state_decorator
def generate_graph(random_state, n_nodes):
    # Generate a random graph using the given random state
    G = nx.gnp_random_graph(n_nodes, random_state.uniform(0.1, 0.5))
    return G

