import networkx as nx
import numpy as np

def dict_to_2d_array(data_dict, mapping=None):
    # Create a directed graph from the dictionary
    G = nx.DiGraph(data_dict)

    # Get the nodes in the order as per the mapping if provided
    if mapping:
        nodes = mapping
    else:
        nodes = list(G.nodes())

    # Initialize a 2D numpy array
    array_size = len(nodes)
    array = np.zeros((array_size, array_size))

    # Fill the numpy array with the weights from the dictionary
    for i, node_i in enumerate(nodes):
        for j, node_j in enumerate(nodes):
            if G.has_edge(node_i, node_j):
                array[i, j] = G[node_i][node_j].get('weight', 1)  # Default weight is 1

    return array
